package expr

import (
	"fmt"
	"math"
	"strconv"
	"strings"
	"unicode"
	"unicode/utf8"
)

// debugForm is the debug form of a thrown value that is not an Error, which
// Windmill's evaluator prints after "Exception generated by quickjs: "
// (JE-21): rquickjs 0.11.0's type name, then the payload in Rust's debug
// notation.
//
//   - a boolean, a number held as a 32-bit integer and any other number:
//     Bool(true), Int(1), Float(1.5), Float(1e300), Float(NaN);
//   - a string: String(Ok("s")), the payload being the result of reading
//     it, quoted and escaped; a string that does not read as UTF-8 (one
//     holding an unpaired surrogate) gives String(Err(Utf8(…))) with Rust's
//     description of where the bytes stop being UTF-8;
//   - a BigInt: BigInt"BigInt", whatever its value;
//   - a symbol, an array, a constructor (a class or a function declared
//     with function), any other function, a Promise, a Proxy and any other
//     object: Symbol, Array, Constructor, Function, Promise, Proxy or Object
//     and the engine's address of the value, Object(0x…), which changes
//     from run to run.
func debugForm(v ThrownValue) string {
	switch v.Kind {
	case KindBool:
		return "Bool(" + strconv.FormatBool(v.Bool) + ")"
	case KindInt:
		return "Int(" + strconv.Itoa(int(v.Int)) + ")"
	case KindFloat:
		return "Float(" + debugFloat(v.Float) + ")"
	case KindString:
		if utf8.ValidString(v.String) {
			return "String(Ok(" + debugString(v.String) + "))"
		}
		return "String(Err(Utf8(" + debugUTF8Error([]byte(v.String)) + ")))"
	case KindBigInt:
		return `BigInt"BigInt"`
	case KindSymbol, KindArray, KindConstructor, KindFunction, KindPromise, KindProxy, KindObject:
		return kindNames[v.Kind] + fmt.Sprintf("(%#x)", v.Address)
	}
	return `Unknown"unknown"`
}

var kindNames = map[ValueKind]string{
	KindSymbol:      "Symbol",
	KindArray:       "Array",
	KindConstructor: "Constructor",
	KindFunction:    "Function",
	KindPromise:     "Promise",
	KindProxy:       "Proxy",
	KindObject:      "Object",
}

// debugFloat is Rust's debug notation of an f64: the shortest digits that
// read back as f, in decimal with at least one fractional digit (1.0,
// 1.5, 100.0), or in exponent notation (1e16, 1.5e-7) when the magnitude
// is at least 1e16 or below 1e-4 and not zero; NaN, inf and -inf; -0.0
// keeps its sign.
func debugFloat(f float64) string {
	switch {
	case math.IsNaN(f):
		return "NaN"
	case math.IsInf(f, 1):
		return "inf"
	case math.IsInf(f, -1):
		return "-inf"
	}
	sign := ""
	if math.Signbit(f) {
		sign = "-"
	}
	a := math.Abs(f)
	if a == 0 {
		return sign + "0.0"
	}
	digits, k := shortestDigits(a)
	// The value is 0.<digits> × 10^k.
	if a < 1e-4 || a >= 1e16 {
		s := digits[:1]
		if len(digits) > 1 {
			s += "." + digits[1:]
		}
		return sign + s + "e" + strconv.Itoa(k-1)
	}
	switch {
	case k <= 0:
		return sign + "0." + strings.Repeat("0", -k) + digits
	case k < len(digits):
		return sign + digits[:k] + "." + digits[k:]
	}
	return sign + digits + strings.Repeat("0", k-len(digits)) + ".0"
}

// shortestDigits returns the digits Rust's shortest formatting gives for a
// finite a > 0, and the exponent k with a's value 0.<digits> × 10^k: the
// fewest digits that read back as a, and of the numbers with that many
// digits that do, the one nearest a's exact value, the greater on a tie.
// Go's shortest formatting finds the same number of digits but can break
// that tie the other way (1000000000000000.25 is 1000000000000000.2 in Go
// and 1000000000000000.3 in Rust), so the digits are chosen here, between
// the two neighbours of the exact value at that length.
func shortestDigits(a float64) (string, int) {
	mant, _, _ := strings.Cut(strconv.FormatFloat(a, 'e', -1, 64), "e")
	n := len(mant) - strings.Count(mant, ".")
	// A float64 has at most 767 significant decimal digits, so 800 give
	// its exact value.
	mant, e, _ := strings.Cut(strconv.FormatFloat(a, 'e', 800, 64), "e")
	exact := strings.Replace(mant, ".", "", 1)
	exp, _ := strconv.Atoi(e)
	lower, rest := exact[:n], strings.TrimRight(exact[n:], "0")
	if rest == "" {
		return strings.TrimRight(lower, "0"), exp + 1
	}
	upper, upExp := incrementDigits(lower), exp
	if len(upper) > n {
		upper, upExp = upper[:n], exp+1
	}
	readsBack := func(d string, x int) bool {
		v, err := strconv.ParseFloat(d[:1]+"."+d[1:]+"e"+strconv.Itoa(x), 64)
		return err == nil && v == a
	}
	lowOK, upOK := readsBack(lower, exp), readsBack(upper, upExp)
	// The exact value lies above lower by rest, a fraction of one unit in
	// the last digit: below one half favours lower, a half or more upper.
	if lowOK && (!upOK || rest < "5") {
		return strings.TrimRight(lower, "0"), exp + 1
	}
	return strings.TrimRight(upper, "0"), upExp + 1
}

// incrementDigits adds one to the decimal digit string d, which grows by a
// digit when it is all nines.
func incrementDigits(d string) string {
	b := []byte(d)
	for i := len(b) - 1; i >= 0; i-- {
		if b[i] < '9' {
			b[i]++
			return string(b)
		}
		b[i] = '0'
	}
	return "1" + string(b)
}

// debugString is Rust's debug notation of a string: quoted, with \0, \t,
// \r, \n, \\ and \" escaped, and every character that extends a grapheme
// or is not printable written as \u{<hex>}. Printable is Rust's reading:
// any character outside the categories Cc, Cf, Cs, Co, Zl, Zp, Zs and the
// unassigned ones, and the space. The single quotation mark is not
// escaped. Unicode's tables are Go's, which can lag Rust's by a version
// for characters assigned since.
func debugString(s string) string {
	var b strings.Builder
	b.WriteByte('"')
	for _, r := range s {
		switch r {
		case 0:
			b.WriteString(`\0`)
		case '\t':
			b.WriteString(`\t`)
		case '\r':
			b.WriteString(`\r`)
		case '\n':
			b.WriteString(`\n`)
		case '\\':
			b.WriteString(`\\`)
		case '"':
			b.WriteString(`\"`)
		default:
			if unicode.In(r, unicode.Mn, unicode.Me, unicode.Other_Grapheme_Extend) || !debugPrintable(r) {
				fmt.Fprintf(&b, `\u{%x}`, r)
			} else {
				b.WriteRune(r)
			}
		}
	}
	b.WriteByte('"')
	return b.String()
}

func debugPrintable(r rune) bool {
	return r == ' ' || unicode.In(r, unicode.L, unicode.M, unicode.N, unicode.P, unicode.S)
}

// debugUTF8Error is the debug notation of the error Rust's UTF-8 check
// reports for b, which is not UTF-8: Utf8Error { valid_up_to: <n>,
// error_len: Some(<k>) }, where n is the length of b's valid prefix and k
// the length of the invalid sequence after it, or error_len: None when b
// ends in the middle of a sequence.
func debugUTF8Error(b []byte) string {
	n := 0
	for n < len(b) {
		r, size := utf8.DecodeRune(b[n:])
		if r == utf8.RuneError && size <= 1 {
			break
		}
		n += size
	}
	errorLen := "None"
	if k := invalidLength(b[n:]); k > 0 {
		errorLen = "Some(" + strconv.Itoa(k) + ")"
	}
	return fmt.Sprintf("Utf8Error { valid_up_to: %d, error_len: %s }", n, errorLen)
}

// invalidLength is how many bytes of the invalid sequence at the start of b
// Rust's UTF-8 check reports: the bytes of the sequence its first byte
// begins that are valid so far, 1 at least, or 0 when b ends before the
// sequence is complete or shown invalid.
func invalidLength(b []byte) int {
	first := b[0]
	cont := func(i int) (bool, bool) {
		if i >= len(b) {
			return false, true
		}
		return b[i]&0xC0 == 0x80, false
	}
	var width int
	switch {
	case first >= 0xC2 && first <= 0xDF:
		width = 2
	case first >= 0xE0 && first <= 0xEF:
		width = 3
	case first >= 0xF0 && first <= 0xF4:
		width = 4
	default:
		return 1
	}
	if len(b) < 2 {
		return 0
	}
	// The second byte's range depends on the first.
	lo, hi := byte(0x80), byte(0xBF)
	switch first {
	case 0xE0:
		lo = 0xA0
	case 0xED:
		hi = 0x9F
	case 0xF0:
		lo = 0x90
	case 0xF4:
		hi = 0x8F
	}
	if b[1] < lo || b[1] > hi {
		return 1
	}
	for i := 2; i < width; i++ {
		ok, end := cont(i)
		if end {
			return 0
		}
		if !ok {
			return i
		}
	}
	// A complete, valid sequence: not reached for text that DecodeRune
	// rejected.
	return width
}
